// Which part of the shop database each API action reads. See planFor() in handler.mjs.
// TABLE_HINTS is generated by scripts/trace-table-hints.mjs from the test suites; a hint that is
// too narrow is safe (the gateway loads the missing table and re-runs), it is only slower.

// Row-filtered reads written in SQL (karvio_snapshot_request / karvio_snapshot_for).
export const ROW_SCOPED_ACTIONS = new Set([
  'bootstrap', 'products.list', 'customers.list', 'suppliers.list', 'accounts.list',
  'sale.create', 'purchase.create', 'sale.detail', 'purchase.detail',
  'customer.payment', 'supplier.payment', 'account.entry',
  // expense.create / expense.update read the whole month for the Monthly expenses limit, so they use table hints.
  'expenses.list', 'account.ledger',
  'login', 'logout', 'users.list', 'sms.log',
]);

// Read-only screens narrowed by date range or party in karvio_snapshot_scoped (falls back to tables).
export const NARROW_READ_ACTIONS = new Set(['customer.statement', 'supplier.statement', 'sales.list', 'sreturns.list']);

